def.body:
if snapshot.dynamic_memory.size == @memory.write_limit
else
  raise(RuntimeError.new("Save data size mismatch: expected #{@memory.write_limit}, got #{snapshot.dynamic_memory.size}"))
end

snapshot.dynamic_memory.copy_to(@memory.bytes.to_slice[0, @memory.write_limit])
@pc = snapshot.pc
@stack = snapshot.stack.dup
@locals = snapshot.locals.dup
@call_stack = clone_call_stack(snapshot.call_stack)
@arg_count = snapshot.arg_count
@memory_streams = snapshot.memory_streams.dup
@screen_stream_on = snapshot.screen_stream_on
@transcript_on = snapshot.transcript_on
@command_recording_on = snapshot.command_recording_on
@rng_seed = snapshot.rng_seed
@halted = false

case window
when -1
  @upper.clear
  @selected = 0
when -2, 1
  @upper.each(&.fill(' '))
  @dirty = false
when 0
  nil
else
  raise(ArgumentError.new("Invalid Z-machine window #{window}"))
end
@upper_row = 1
@upper_column = 1

if @selected == 1
else
  return
end
@upper_row = row.clamp(1, Math.max(@upper.size, 1))
@upper_column = column.clamp(1, screen_width)

if (window == 0) || (window == 1)
else
  raise(ArgumentError.new("Invalid Z-machine window #{window}"))
end
if window == 0
  flush_upper
end
@selected = window
if window == 1
  @upper_row = 1
  @upper_column = 1
end

height = lines.clamp(0, screen_height)
width = screen_width
previous = @upper
@upper = Array.new(height) do |row|
  Array.new(width) do |column| previous[row]?.try(&.[]?(column)) || ' ' end
end
@upper_row = @upper_row.clamp(1, Math.max(height, 1))
@upper_column = @upper_column.clamp(1, width)

if @selected == 0
  @inner.write(text)
  text.each_char do |char|
    if char == '\n'
      @lower_row = @lower_row + 1
      @lower_column = 1
    else
      @lower_column = @lower_column + 1
    end
  end
  return
end

text.each_char do |char|
  if char == '\n'
    @upper_row = @upper_row + 1
    @upper_column = 1
  elsif @upper_row <= @upper.size && @upper_column <= screen_width
    @upper[@upper_row - 1][@upper_column - 1] = char
    @upper_column = @upper_column + 1
    @dirty = true
  end
end
